local t = {
	COMMON_WEIGHT = 75,
	UNCOMMON_WEIGHT = 25,
	RARE_BASE_WEIGHT = 10,
	RARE_FLOOR_THRESHOLD = 5,
	RARE_WEIGHT_PER_STEP = 1,
	RARE_INTERVAL = 2,
	MAIN_BASE_WEIGHT = 4,
	MAIN_FLOOR_THRESHOLD = 5,
	MAIN_WEIGHT_PER_STEP = 4,
	MAIN_INTERVAL = 5,
	DANDY_WEIGHT_PER_NOBUY = 5,
	DANDY_NOBUY_THRESHOLD = 2,
	MILESTONE_MAIN_FLOOR = 20,
	MILESTONE_RARE_FLOOR = 15,
	NATURAL_MILESTONE_SPAWNS = true
}

function t.GetRareWeight(p1) --[[ GetRareWeight | Line: 32 | Upvalues: t (copy) ]]
	if t.RARE_FLOOR_THRESHOLD <= p1 then
		return t.RARE_BASE_WEIGHT + t.RARE_WEIGHT_PER_STEP * (math.floor((p1 - t.RARE_FLOOR_THRESHOLD) / math.max(t.RARE_INTERVAL, 1)) + 1)
	end

	return t.RARE_BASE_WEIGHT
end
function t.GetMainWeight(p1) --[[ GetMainWeight | Line: 42 | Upvalues: t (copy) ]]
	if t.MAIN_FLOOR_THRESHOLD <= p1 then
		return t.MAIN_WEIGHT_PER_STEP * math.floor((p1 - t.MAIN_FLOOR_THRESHOLD) / math.max(t.MAIN_INTERVAL, 1)) + t.MAIN_BASE_WEIGHT
	end

	return 0
end

return t